-- product_script: Sandboxed WASM module implementing custom product behaviour at a lifecycle hook
CREATE TABLE product_script (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  product_version_id           uuid NOT NULL REFERENCES product_version(id),
  name                         varchar(120) NOT NULL,
  hook                         varchar(40) NOT NULL CHECK (hook IN ('PRE_POSTING', 'POST_POSTING', 'ACCRUAL', 'FEE_CALCULATION', 'SCHEDULE_GENERATION', 'ELIGIBILITY', 'END_OF_DAY', 'END_OF_MONTH', 'ON_MATURITY', 'ON_EVENT')),
  language                     varchar(40) NOT NULL CHECK (language IN ('RUST', 'ASSEMBLYSCRIPT', 'TYPESCRIPT', 'TINYGO')),
  source_code                  text,
  wasm_module_uri              varchar(500) NOT NULL,
  wasm_sha256                  varchar(64) NOT NULL,
  entrypoint                   varchar(64) NOT NULL DEFAULT 'run',
  max_fuel                     bigint NOT NULL DEFAULT 10000000,
  max_memory_mb                integer NOT NULL DEFAULT 16,
  timeout_ms                   integer NOT NULL DEFAULT 50,
  status                       varchar(40) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'VALIDATED', 'PENDING_APPROVAL', 'ACTIVE', 'DEPRECATED', 'REJECTED')),
  validation_report            jsonb,
  approved_by                  varchar(64),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_product_script_1 UNIQUE (product_version_id, hook, name)
);
COMMENT ON TABLE product_script IS 'Sandboxed WASM module implementing custom product behaviour at a lifecycle hook';
COMMENT ON COLUMN product_script.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN product_script.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN product_script.created_at IS 'Creation time';
COMMENT ON COLUMN product_script.created_by IS 'Principal that created the row';
