-- interest_rate_config: Interest configuration of a product version (credit, debit, overdraft, penalty, APRs)
CREATE TABLE interest_rate_config (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  product_version_id           uuid NOT NULL REFERENCES product_version(id),
  rate_kind                    varchar(40) NOT NULL CHECK (rate_kind IN ('CREDIT_INTEREST', 'DEBIT_INTEREST', 'OVERDRAFT_INTEREST', 'UNARRANGED_OVERDRAFT_INTEREST', 'PENALTY_INTEREST', 'BONUS_INTEREST', 'PURCHASE_APR', 'CASH_ADVANCE_APR', 'BALANCE_TRANSFER_APR')),
  rate_type                    varchar(40) NOT NULL CHECK (rate_type IN ('FIXED', 'TIERED', 'BANDED', 'FLOATING', 'STEPPED', 'ZERO')),
  fixed_rate                   numeric(18,10),
  rate_index_id                uuid REFERENCES rate_index(id),
  spread                       numeric(18,10),
  floor_rate                   numeric(18,10),
  cap_rate                     numeric(18,10),
  day_count                    varchar(40) NOT NULL DEFAULT 'ACT_365' CHECK (day_count IN ('ACT_360', 'ACT_365', 'ACT_365L', 'ACT_ACT_ISDA', 'THIRTY_360', 'THIRTY_E_360')),
  balance_basis                varchar(40) NOT NULL DEFAULT 'END_OF_DAY' CHECK (balance_basis IN ('END_OF_DAY', 'AVERAGE_DAILY', 'MINIMUM_DAILY', 'MINIMUM_MONTHLY')),
  accrual_frequency            varchar(40) NOT NULL DEFAULT 'DAILY' CHECK (accrual_frequency IN ('DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL', 'AT_MATURITY', 'NONE')),
  compounding_frequency        varchar(40) NOT NULL DEFAULT 'NONE' CHECK (compounding_frequency IN ('DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL', 'AT_MATURITY', 'NONE')),
  capitalisation_frequency     varchar(40) NOT NULL DEFAULT 'MONTHLY' CHECK (capitalisation_frequency IN ('DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL', 'AT_MATURITY', 'NONE')),
  capitalisation_day           integer,
  reprice_frequency            varchar(40) CHECK (reprice_frequency IN ('DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL', 'AT_MATURITY', 'NONE')),
  min_balance_for_interest     numeric(28,8) NOT NULL DEFAULT 0,
  rounding                     varchar(40) NOT NULL DEFAULT 'HALF_EVEN' CHECK (rounding IN ('HALF_EVEN', 'HALF_UP', 'HALF_DOWN', 'UP', 'DOWN')),
  rounding_scale               integer NOT NULL DEFAULT 2,
  currency                     char(3) NOT NULL,
  effective_from               date NOT NULL,
  effective_to                 date,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
