  frequency                    varchar(40) CHECK (frequency IN ('DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'SEMI_ANNUAL', 'ANNUAL', 'AT_MATURITY', 'NONE')),
  calculation_method           varchar(40) NOT NULL CHECK (calculation_method IN ('FLAT', 'PERCENTAGE', 'FLAT_PLUS_PERCENTAGE', 'TIERED_FLAT', 'TIERED_PERCENTAGE', 'PER_UNIT')),
