  cap_per_period               numeric(28,8),
  cap_period                   varchar(40) CHECK (cap_period IN ('PER_TRANSACTION', 'DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY', 'LIFETIME')),
  free_count                   integer NOT NULL DEFAULT 0,
