-- fee_waiver_rule: Condition under which a fee is waived or discounted
CREATE TABLE fee_waiver_rule (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  fee_definition_id            uuid NOT NULL REFERENCES fee_definition(id),
  condition                    varchar(40) NOT NULL CHECK (condition IN ('MIN_BALANCE', 'AVERAGE_BALANCE', 'SALARY_CREDIT', 'TRANSACTION_COUNT', 'BUNDLE_MEMBER', 'SEGMENT', 'PROMOTION', 'MANUAL', 'FIRST_N_FREE')),
  threshold_amount             numeric(28,8),
  threshold_count              integer,
  segment                      varchar(40) CHECK (segment IN ('RETAIL', 'SME', 'CORPORATE', 'PRIVATE', 'YOUTH', 'STUDENT', 'SENIOR', 'STAFF', 'GOVERNMENT', 'NON_PROFIT')),
  discount_percentage          numeric(18,10) NOT NULL DEFAULT 1,
  expression                   text,
  valid_from                   date,
  valid_to                     date,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE fee_waiver_rule IS 'Condition under which a fee is waived or discounted';
COMMENT ON COLUMN fee_waiver_rule.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN fee_waiver_rule.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN fee_waiver_rule.created_at IS 'Creation time';
