COMMENT ON COLUMN fee_waiver_rule.updated_at IS 'Last update time';
COMMENT ON COLUMN fee_waiver_rule.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN fee_waiver_rule.row_version IS 'Optimistic lock version; send as If-Match';
