COMMENT ON COLUMN fee_waiver_rule.threshold_count IS 'Threshold for count conditions';
COMMENT ON COLUMN fee_waiver_rule.segment IS 'Segment for SEGMENT condition';
COMMENT ON COLUMN fee_waiver_rule.discount_percentage IS 'Share waived (1 = fully waived)';
