-- product_bundle: Package of products sold together with shared pricing (e.g. account + card + overdraft)
CREATE TABLE product_bundle (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  code                         varchar(64) NOT NULL,
  name                         varchar(160) NOT NULL,
  description                  text,
  monthly_fee                  numeric(28,8) NOT NULL DEFAULT 0,
  currency                     char(3) NOT NULL,
  fee_definition_id            uuid REFERENCES fee_definition(id),
  status                       varchar(40) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'SUSPENDED', 'RETIRED')),
  valid_from                   date,
  valid_to                     date,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_product_bundle_code UNIQUE (tenant_id, code)
);
