COMMENT ON COLUMN product_bundle.valid_to IS 'End date';
COMMENT ON COLUMN product_bundle.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN product_bundle.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN product_bundle.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
